  "scripts": {
    "build": "bun run generate && bun --conditions=source run ../../tools/documentation/catalogue.runtime.ts",
    "check-types": "tsc --noEmit",
    "generate": "fumadocs-mdx && bun --conditions=source run ./src/catalogue-index.runtime.ts",
    "test": "vitest run --passWithNoTests",
    "validate": "bun run ./src/validate.runtime.ts",
    "clean": "rm -rf .source .turbo *.tsbuildinfo"
  },
  "dependencies": {
    "@effect/platform-bun": "catalog:",
