import * as Schema from "effect/Schema";

const PreviewStage = Schema.String.check(Schema.isPattern(/^pr-[1-9]\d*$/u));

export const DocsLocalDevelopmentStage = Schema.String.check(
  Schema.isPattern(/^dev_[a-z0-9]+(?:[-_a-z0-9]+)*$/iu)
).pipe(Schema.brand("taxkit/LocalDocsDevelopmentStage"));

export const DocsDeploymentStage = Schema.Union([
  Schema.Literals(["prod"]),
  PreviewStage,
]).pipe(Schema.brand("taxkit/DocsDeploymentStage"));
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";

import { DocsDeploymentStage, DocsLocalDevelopmentStage } from "../stage.js";

export const DocsCloudflareStackStage = Schema.Union([
  DocsDeploymentStage,
  DocsLocalDevelopmentStage,
]);

export type DocsCloudflareStackStage = typeof DocsCloudflareStackStage.Type;

export const docsCloudflareStackName = "TaxKitDocsCloudflare";
export const docsWorkerResourceId = "DocsWebsite";
export const docsWorkerCompatibilityDate = "2026-06-24";
export const docsWorkerCompatibilityFlags = ["nodejs_compat"] as const;
export const docsWorkerMemo = {
  include: ["**/*"],
  lockfile: true,
  workspaces: [
    {
      cwd: "../../packages/docs-content",
      include: ["**/*"],
      lockfile: false,
    },
    {
      cwd: "../../packages/docs-fumadocs",
      include: ["**/*"],
      lockfile: false,
    },
  ],
} as const;

export const decodeDocsCloudflareStackStage = (
  value: typeof Schema.Unknown.Type
) =>
  Schema.decodeUnknownEffect(DocsCloudflareStackStage)(value).pipe(
    Effect.mapError((error) => new Config.ConfigError(error))
  );

export const docsWorkerObservability = {
  enabled: true,
  headSamplingRate: 1,
  logs: {
    enabled: true,
    headSamplingRate: 1,
    invocationLogs: true,
    persist: true,
  },
  traces: {
    enabled: false,
    headSamplingRate: 0,
    persist: false,
  },
} as const;
import { describe, expect, it } from "@effect/vitest";
import type { MemoOptions } from "alchemy/Command/Memo";
import { Array, Effect, Exit, Schema } from "effect";

import { DocsDeploymentStage } from "../stage.js";
import {
  decodeDocsCloudflareStackStage,
  docsWorkerMemo,
  docsWorkerObservability,
} from "./website.js";

const decodeDocsDeploymentStage =
  Schema.decodeUnknownEffect(DocsDeploymentStage);

describe("docs Cloudflare stack policy", () => {
  it.effect("requires copying readonly memo arrays at Alchemy input", () =>
    Effect.gen(function* () {
      // @ts-expect-error The provider's include field requires a fresh writable array.
      const mutableInclude: MemoOptions["include"] = docsWorkerMemo.include;
      const workspace = yield* Effect.fromOption(
        Array.head(docsWorkerMemo.workspaces)
      );
      // @ts-expect-error Nested workspace arrays also require a fresh boundary copy.
      const mutableWorkspaceInclude: MemoOptions["include"] = workspace.include;
      expect(mutableInclude).toBe(docsWorkerMemo.include);
      expect(mutableWorkspaceInclude).toBe(workspace.include);
    })
  );
  it.effect.each(["prod", "pr-1", "pr-214"])(
    "accepts the owned deployment stage %s",
    (stage) =>
      Effect.gen(function* () {
        expect(yield* decodeDocsDeploymentStage(stage)).toBe(stage);
      })
  );

  it.effect.each(["", "preview", "pr-0", "pr-01", "prod-2"])(
    "rejects the unowned deployment stage %s",
    (stage) =>
      Effect.gen(function* () {
        expect(
          Exit.isFailure(yield* Effect.exit(decodeDocsDeploymentStage(stage)))
        ).toBe(true);
      })
  );

  it.effect.each(["dev_cooper", "dev_taxkit-maintainer", "dev_ci_user"])(
    "accepts the local-only stack stage %s",
    (stage) =>
      Effect.gen(function* () {
        expect(yield* decodeDocsCloudflareStackStage(stage)).toBe(stage);
        expect(
          Exit.isFailure(yield* Effect.exit(decodeDocsDeploymentStage(stage)))
        ).toBe(true);
      })
  );

  it.effect.each(["dev", "dev_", "dev user", "development_cooper"])(
    "rejects the invalid local stack stage %s",
    (stage) =>
      Effect.gen(function* () {
        expect(
          Exit.isFailure(
            yield* Effect.exit(decodeDocsCloudflareStackStage(stage))
          )
        ).toBe(true);
      })
  );

  it("keeps built-in logs bounded and traces disabled", () => {
    expect(docsWorkerObservability).toEqual({
      enabled: true,
      headSamplingRate: 1,
      logs: {
        enabled: true,
        headSamplingRate: 1,
        invocationLogs: true,
        persist: true,
      },
      traces: {
        enabled: false,
        headSamplingRate: 0,
        persist: false,
      },
    });
  });
});
