  );

/**
 * Pure inspection over files the runtime has already read. Each finding names
 * the document and the broken reference so the author can repair it directly.
 */
export const inspectDocumentation = ({
  files,
  exists,
  scripts,
}: Readonly<{
  files: readonly DocumentationFile[];
  exists: (repositoryPath: string) => boolean;
  scripts: ScriptOwners;
}>): readonly string[] =>
  Array.flatMap(files, (file) => {
    const directory = file.path.includes("/")
      ? file.path.slice(0, file.path.lastIndexOf("/"))
      : "";
    const metadata =
      file.path.startsWith("docs/") && file.path.endsWith(".md")
        ? Option.match(Option.fromNullishOr(frontmatter.exec(file.text)), {
            onNone: () => [`${file.path}: missing maintainer metadata`],
            onSome: (match) => {
              const body = match.groups?.["body"] ?? "";
              return hasFields(body, currentFields) ||
                hasFields(body, legacyFields)
                ? []
                : [`${file.path}: incomplete maintainer metadata`];
            },
          })
        : [];
    // Completed plans and dated records keep the links and commands of their
    // time; Git retains the files they name.
    const current =
      !file.path.startsWith("docs/") ||
      /^lifecycle:\s*current\s*$/mu.test(
        frontmatter.exec(file.text)?.groups?.["body"] ?? ""
      );
    const links = Array.getSomes(Array.map(
      current
        ? Array.fromIterable(file.text.replace(code, "").matchAll(markdownLink))
        : [],
      (match) => {
        const target = (match.groups?.["target"] ?? "").split("#")[0] ?? "";
        if (
          target === "" ||
          /^[a-z][a-z0-9+.-]*:/iu.test(target) ||
          target.startsWith("/")
        ) {
          return Option.none();
        }
        const resolved = normalise(
          directory === "" ? target : `${directory}/${target}`
        );
        return Option.match(resolved, {
          onNone: () => Option.some(`${file.path}: link leaves the repository: ${target}`),
          onSome: (candidate) =>
            exists(candidate)
              ? Option.none()
              : Option.some(`${file.path}: broken link: ${target}`),
        });
      }
    ));
    const commands = Array.getSomes(Array.map(
      current ? Array.fromIterable(file.text.matchAll(bunRun)) : [],
      (match) => {
        const command = match.groups?.["command"] ?? "";
        const filter = Option.fromNullishOr(match.groups?.["filter"]);
        return Option.match(filter, {
          onNone: () =>
            HashSet.has(scripts.root, command) ||
            Option.exists(
              HashMap.get(scripts.workspaces, directory),
              (owned) => HashSet.has(owned, command)
            )
              ? Option.none()
              : Option.some(`${file.path}: unknown root command: bun run ${command}`),
          onSome: (workspace) =>
            Option.match(HashMap.get(scripts.workspaces, workspace), {
              // Glob and path filters are not checked here.
              onNone: () => Option.none(),
              onSome: (owned) =>
                HashSet.has(owned, command)
                  ? Option.none()
                  : Option.some(
                      `${file.path}: unknown command: bun run --filter=${workspace} ${command}`
                    ),
            }),
        });
      }
    ));
    return [...metadata, ...links, ...commands];
  });

const normalise = (relative: string): Option.Option<string> =>
  Array.reduce(
    relative.split("/"),
    Option.some<readonly string[]>([]),
    (parts, segment) =>
      Option.flatMap(parts, (current) => {
        if (segment === "" || segment === ".") {
          return Option.some(current);
        }
        if (segment === "..") {
          return current.length === 0
            ? Option.none()
            : Option.some(current.slice(0, -1));
        }
        return Option.some([...current, decodeURIComponent(segment)]);
      })
  ).pipe(Option.map((parts) => parts.join("/")));

const workspaceRoots = [
  "apps",
  "packages",
  "packages/api",
  "packages/sdk",
  "packages/rules/au",
] as const;

export const checkDocumentation = Effect.fn("Documentation.check")(function* (
  repositoryRoot: string
) {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const readScripts = (manifest: string) =>
    fs.readFileString(manifest).pipe(
      Effect.flatMap(Schema.decodeEffect(PackageScripts)),
      Effect.map((decoded) => ({
        name: Option.fromNullishOr(decoded.name),
        scripts: HashSet.fromIterable(Object.keys(decoded.scripts ?? {})),
      }))
    );
  const root = yield* readScripts(path.join(repositoryRoot, "package.json"));
  const workspaceDirectories = yield* Effect.forEach(
    workspaceRoots,
    (parent) =>
      fs.readDirectory(path.join(repositoryRoot, parent)).pipe(
        Effect.map(Array.map((entry) => `${parent}/${entry}`))
      )
  ).pipe(Effect.map(Array.flatten));
  const workspaces = yield* Effect.filter(workspaceDirectories, (directory) =>
    fs.exists(path.join(repositoryRoot, directory, "package.json"))
  );
  const manifests = yield* Effect.forEach(workspaces, (directory) =>
    readScripts(path.join(repositoryRoot, directory, "package.json")).pipe(
      Effect.map((manifest) => ({ directory, manifest }))
    )
  );
  const docs = yield* fs
    .readDirectory(path.join(repositoryRoot, "docs"), { recursive: true })
    .pipe(
      Effect.map((entries) =>
        Array.map(
          Array.filter(entries, (entry) => entry.endsWith(".md")),
          (entry) => `docs/${entry}`
        )
      )
    );
  const readmes = yield* Effect.filter(
    Array.map(workspaces, (directory) => `${directory}/README.md`),
    (readme) => fs.exists(path.join(repositoryRoot, readme))
  );
  const files = yield* Effect.forEach(
    ["AGENTS.md", "README.md", ...docs, ...readmes],
    (file) =>
      fs
        .readFileString(path.join(repositoryRoot, file))
        .pipe(Effect.map((text) => ({ path: file, text })))
  );
  const existing = yield* Effect.forEach(
    HashSet.fromIterable(
      Array.flatMap(files, (file) => {
        const directory = file.path.includes("/")
          ? file.path.slice(0, file.path.lastIndexOf("/"))
          : "";
        return Array.getSomes(Array.map(
          Array.fromIterable(file.text.replace(code, "").matchAll(markdownLink)),
          (match) =>
            normalise(
              directory === ""
                ? ((match.groups?.["target"] ?? "").split("#")[0] ?? "")
                : `${directory}/${(match.groups?.["target"] ?? "").split("#")[0] ?? ""}`
            )
        ));
      })
    ),
    (candidate) =>
      fs
        .exists(path.join(repositoryRoot, candidate))
        .pipe(Effect.map((found) => [candidate, found] as const))
  ).pipe(Effect.map(HashMap.fromIterable));
  const findings = inspectDocumentation({
    exists: (candidate) =>
      HashMap.get(existing, candidate).pipe(Option.getOrElse(() => false)),
    files,
    scripts: {
      root: root.scripts,
      workspaces: HashMap.fromIterable(
        Array.flatMap(manifests, ({ directory, manifest }) => [
          [directory, manifest.scripts] as const,
          ...Option.match(manifest.name, {
            onNone: () => [],
            onSome: (name) => [[name, manifest.scripts] as const],
          }),
        ])
      ),
    },
  });
  if (findings.length > 0) {
    return yield* new DocumentationError({ findings });
  }
  return files.length;
});

