import { CalculatorRpcOrigin } from "@taxkit/api-rpc/schemas";
import { DocsWebsiteOrigin } from "@taxkit/content/schemas";
import { Schema } from "effect";

const ApiServerHostSchema = Schema.NonEmptyString;

const ApiServerPortSchema = Schema.Int.check(
  Schema.isBetween({
    maximum: 65_535,
    minimum: 1,
  })
);

export const ApiServerConfigSourceSchema = Schema.Struct({
  host: ApiServerHostSchema,
  port: ApiServerPortSchema,
});

export const ApiServerTcpAddressSchema = Schema.TaggedStruct("TcpAddress", {
  hostname: ApiServerHostSchema,
  port: ApiServerPortSchema,
});

export const ApiServerConfigSchema = Schema.Struct({
  address: ApiServerTcpAddressSchema,
});

export type ApiServerConfigService = Schema.Schema.Type<
  typeof ApiServerConfigSchema
>;

export class ApiServerConfigError extends Schema.TaggedError<ApiServerConfigError>()(
  "ApiServerConfigError",
  { operation: Schema.Literal("settings") }
) {}

export const ApiWorkerSettings = Schema.Struct({
  apiOrigin: CalculatorRpcOrigin,
  websiteOrigin: DocsWebsiteOrigin,
});

export type ApiWorkerSettings = typeof ApiWorkerSettings.Type;
import { CalculatorClientRateKey } from "@taxkit/calculators/admission.schemas";
import { Option, Schema } from "effect";
import { Headers } from "effect/http";

export { CalculatorClientRateKey } from "@taxkit/calculators/admission.schemas";
export { CalculatorRequestRateKey } from "@taxkit/calculators/admission.service";

export const CalculatorHostMode = Schema.Literals(["edge", "local-emulator"]);
export type CalculatorHostMode = typeof CalculatorHostMode.Type;

// Only direct Cloudflare edge requests supply this identity. Same-zone Worker
// subrequests can alter x-real-ip; reject that path instead of trusting it.
// Website forwarding uses the separate private binding method, never a header.
export const calculatorEdgeRateKey = (
  headers: Headers.Headers
): Option.Option<typeof CalculatorClientRateKey.Type> =>
  Option.isSome(Headers.get(headers, "cf-worker"))
    ? Option.none()
    : Headers.get(headers, "cf-connecting-ip").pipe(
        Option.flatMap(Schema.decodeUnknownOption(CalculatorClientRateKey))
      );
import { Schema } from "effect";

// This is data, never an Effect or a Stack. Alchemy must reject it before
// constructing session services, providers or remote state.
export class RetiredDocsStack extends Schema.TaggedClass<RetiredDocsStack>()(
  "RetiredDocsStack",
  {
    reason: Schema.Literal(
      "The old docs app and its default Stack are retired."
    ),
    recoveryRecord: Schema.Literal(
      "docs/documentation-audit/clean-slate-foundation/2026-10-07-docs-retirement-manifest.json"
    ),
  }
) {}
import { RetiredDocsStack } from "@taxkit/infrastructure/stack";

export default new RetiredDocsStack({
  reason: "The old docs app and its default Stack are retired.",
  recoveryRecord:
    "docs/documentation-audit/clean-slate-foundation/2026-10-07-docs-retirement-manifest.json",
});

