cat > alchemy.run.ts <<'EOF'
import { declareNativeAppsStack } from "@taxkit/infrastructure/apps-stack";
import { deploymentSecrets } from "@taxkit/infrastructure/secrets";
import * as Alchemy from "alchemy";
import * as Cloudflare from "alchemy/Cloudflare";

// The Website/API pair for `prod` and `pr-<number>` stages. The stack name
// and resource IDs are the existing state identity; do not rename them.
export default Alchemy.Stack(
  "TaxKitAppsCloudflare",
  {
    providers: Cloudflare.providers(),
    secrets: deploymentSecrets,
    state: Cloudflare.state(),
  },
  declareNativeAppsStack
);
EOF
git mv alchemy.apps.local.run.ts alchemy.local.run.ts; git rm -q alchemy.apps.run.ts; cat tsconfig.alchemy.json; python3 - <<'EOF'
import json
p='packages/infrastructure/package.json'; d=json.load(open(p))
e=d['exports']
for k in ['./stack','./stage','./website','./apps-secrets']: e.pop(k,None)
e['./secrets']={"source":"./src/secrets.ts","types":"./src/secrets.ts","default":"./src/secrets.ts"}
e['./stage']={"source":"./src/stage.ts","types":"./src/stage.ts","default":"./src/stage.ts"}
json.dump(d,open(p,'w'),indent=2); open(p,'a').write('\n')
EOF
grep -rn 'infrastructure/\(stack\|stage\|website\|apps-secrets\)' --include=*.ts . 2>/dev/null | grep -v node_modules; git grep -n '@taxkit/infrastructure/' -- '*.ts' '*.tsx' | grep -v '^packages/infrastructure'

