          const incoming = yield* HttpServerRequest.HttpServerRequest;
          return yield* relay.handle(incoming).pipe(
            Effect.catchTag("WebsiteRelayFailure", (error) =>
              Effect.succeed(
                HttpServerResponse.empty({
                  headers: { "cache-control": "no-store" },
