import { createFileRoute } from "@tanstack/react-router";
import { Option, Result } from "effect";

import { MdxDocument } from "#/lib/docs/mdx.boundary";
import { docsMetadata } from "#/lib/docs/metadata.egress";
import {
  DocsPageNotFound,
  DocsPageUnavailable,
  DocsNavigation,
} from "#/lib/docs/page.view";
import { docsPageRouteBoundary } from "#/lib/docs/route-boundary";

export const Route = createFileRoute("/$")({
  component: function DocumentationRoute() {
    // This route alone restores the plain server-function representation.
    const loaderData = Route.useLoaderData();
    const restored = docsPageRouteBoundary.restore(loaderData);
    return Result.match(restored, {
      onFailure: () => <DocsPageUnavailable />,
      onSuccess: ({ navigation, page, settings }) => (
        <div className="docs-layout">
          <aside className="docs-sidebar">
            <DocsNavigation
              currentPath={Option.some(page.path)}
              navigation={navigation}
            />
          </aside>
          <article className="docs-article">
            <MdxDocument page={page} />
            <p className="docs-markdown-link">
              <a
                href={
                  new URL(`${page.path}.md`, settings.publicationOrigin).href
                }
              >
                Read this page as Markdown
              </a>
            </p>
          </article>
        </div>
      ),
    });
  },
  errorComponent: DocsPageUnavailable,
  head: ({ loaderData }) => {
    const restored = docsPageRouteBoundary.restore(loaderData);
    return Result.match(restored, {
      onFailure: () => ({ meta: [{ title: "Documentation | TaxKit" }] }),
      onSuccess: ({ page, settings }) =>
        docsMetadata(page, settings).pipe(
          Result.getOrElse(() => ({
            meta: [{ title: "Documentation | TaxKit" }],
          }))
        ),
    });
  },
  loader: ({ params, context, abortController }) =>
    context.loadDocsPage({
      path: `/${params._splat}`,
      signal: abortController.signal,
    }),
  notFoundComponent: DocsPageNotFound,
  pendingComponent: () => (
    <section aria-busy="true" aria-live="polite" className="docs-state">
      <h1>Loading documentation</h1>
      <p>The requested page is being loaded.</p>
    </section>
  ),
  pendingMs: 150,
});
import { createFileRoute } from "@tanstack/react-router";
import { Match, Option, Result } from "effect";

import { DocsHeading } from "#/lib/docs/components";
import { DocsNavigation } from "#/lib/docs/page.view";
import { docsSearchRouteBoundary } from "#/lib/docs/route-boundary";
import { readDocsSearchLocation } from "#/lib/docs/search-location.boundary";
import { DocsSearchForm, DocsSearchResults } from "#/lib/docs/search.view";

const SearchUnavailable = () => (
  <section className="docs-state" role="alert">
    <DocsHeading>Search documentation</DocsHeading>
    <p>
      Documentation search could not load. Please reload this page to try again.
    </p>
    <DocsSearchForm term="" />
    <a href="/start/quickstart">Open the Quickstart</a>
  </section>
);

export const Route = createFileRoute("/search")({
  component: function DocumentationSearchRoute() {
    const restored = docsSearchRouteBoundary.restore(Route.useLoaderData());
    return Result.match(restored, {
      onFailure: (error) => (
        <section className="docs-state" role="alert">
          <DocsHeading>Search documentation</DocsHeading>
          <p>
            {Match.value(error).pipe(
              Match.tag(
                "DocsSearchInputError",
                () => "Enter up to 100 characters to search the documentation."
              ),
              Match.orElse(
                () =>
                  "Documentation search could not load. Please reload this page to try again."
              )
            )}
          </p>
          <DocsSearchForm term="" />
          <a href="/start/quickstart">Open the Quickstart</a>
        </section>
      ),
      onSuccess: ({ navigation, results, term }) => (
        <div className="docs-layout">
          <aside className="docs-sidebar">
            <DocsNavigation
              currentPath={Option.none()}
              navigation={navigation}
            />
          </aside>
          <article className="docs-article">
            <DocsHeading>Search documentation</DocsHeading>
            <DocsSearchForm term={term} />
            <DocsSearchResults results={results} term={term} />
          </article>
        </div>
      ),
    });
  },
  errorComponent: SearchUnavailable,
  head: () => ({
    meta: [
      { title: "Search documentation | TaxKit" },
      { content: "noindex, follow", name: "robots" },
      {
        content: "Find a TaxKit guide, API reference or integration example.",
        name: "description",
      },
    ],
  }),
  loader: ({ location, context, abortController }) =>
    context.loadDocsSearch({
      query: readDocsSearchLocation(location.searchStr),
      signal: abortController.signal,
    }),
  pendingComponent: () => (
    <section aria-busy="true" aria-live="polite" className="docs-state">
      <h1>Searching documentation</h1>
      <p>Matching pages are being loaded.</p>
    </section>
  ),
  pendingMs: 150,
  // Each original address supplies its own words. Do not reuse a cached result
  // from a previous query or let the framework's JSON query parser change it.
  shouldReload: true,
});
import { Result, Schema } from "effect";

import {
  WebsiteDocsSearchTransport,
  WebsiteDocsPageTransport,
} from "../schemas";
import { DocsRouteTransportError } from "./errors";

// Each direct route is the first consumer of its native representation.
// Children receive only checked values after the route matches the Result.
export const docsPageRouteBoundary = {
  restore: (encoded: typeof Schema.Unknown.Type) =>
    Schema.decodeUnknownResult(WebsiteDocsPageTransport)(encoded).pipe(
      Result.mapError(() => new DocsRouteTransportError()),
      Result.flatMap((result) => result)
    ),
};
export const docsSearchRouteBoundary = {
  restore: (encoded: typeof Schema.Unknown.Type) =>
    Schema.decodeUnknownResult(WebsiteDocsSearchTransport)(encoded).pipe(
      Result.mapError(() => new DocsRouteTransportError()),
      Result.flatMap((result) => result)
    ),
};
import { Array, HashSet, Record, Result, Schema } from "effect";

import { WebsiteDocsSearchLocation, WebsiteSearchParameters } from "../schemas";
import { DocsSearchInputError } from "./errors";

// The Website has literal human query text. The framework's default JSON
// parser changes scientific numbers and quoted words, and its encoder changes
// duplicate keys. Preserve the native URL pairs through both host callbacks.
export const websiteSearchParameters = {
  parse: (raw: string): typeof WebsiteSearchParameters.Type => {
    const query = new URLSearchParams(raw);
    return Record.fromEntries(
      Array.map(
        Array.fromIterable(HashSet.fromIterable(query.keys())),
        (key) => [key, query.getAll(key)]
      )
    );
  },
  stringify: (input: typeof Schema.Unknown.Type) =>
    Schema.decodeUnknownResult(WebsiteSearchParameters)(input).pipe(
      Result.match({
        onFailure: () => "?invalid-search=1",
        onSuccess: (query) => {
          const encoded = new URLSearchParams(
            Array.flatMap(Record.toEntries(query), ([key, values]) =>
              Array.map(values, (value) => [key, value])
            )
          ).toString();
          return encoded === "" ? "" : `?${encoded}`;
        },
      })
    ),
};

// The route's original address is representation ingress, separate from
// restoration of a later encoded loader reply.
export const readDocsSearchLocation = (encoded: typeof Schema.Unknown.Type) =>
  Schema.decodeUnknownResult(WebsiteDocsSearchLocation)(encoded).pipe(
    Result.mapError(() => new DocsSearchInputError())
  );

